304	// redactURL removes credentials from a URL for safe logging.
305	// Handles both HTTPS URLs with embedded credentials and general URLs.
306	func redactURL(rawURL string) string {
307		u, err := url.Parse(rawURL)
308		if err != nil {
309			// For non-URL formats (SSH SCP), just return the host portion
310			if idx := strings.Index(rawURL, "@"); idx >= 0 {
311				if colonIdx := strings.Index(rawURL[idx:], ":"); colonIdx >= 0 {
312					return rawURL[idx+1:idx+colonIdx] + ":***"
313				}
314			}
315			return "<unparseable>"
316		}
317		u.User = nil
318		u.RawQuery = ""
319		host := u.Host
320		path := u.Path
321		return u.Scheme + "://" + host + path
322	}
