324	// ResolveCheckpointRemoteURL resolves the checkpoint remote URL from settings.
325	// Returns (url, true, nil) if a checkpoint_remote is configured and resolved successfully,
326	// ("", false, nil) if no checkpoint_remote is configured, or ("", true, err) if configured
327	// but resolution failed (e.g., missing origin remote, unparseable URL).
328	// Unlike resolvePushSettings, this skips fork detection (reading is always allowed)
329	// and has no side effects (no fetching).
330	func ResolveCheckpointRemoteURL(ctx context.Context) (string, bool, error) {
331		s, err := settings.Load(ctx)
332		if err != nil {
333			return "", false, nil //nolint:nilerr // settings load failure means "can't determine config" — treat as not configured
334		}
335	
336		config := s.GetCheckpointRemote()
337		if config == nil {
338			return "", false, nil
339		}
340	
341		remoteURL, err := getRemoteURL(ctx, "origin")
342		if err != nil {
343			return "", true, fmt.Errorf("could not get origin remote URL: %w", err)
344		}
345	
346		remoteInfo, err := parseGitRemoteURL(remoteURL)
347		if err != nil {
348			return "", true, fmt.Errorf("could not parse origin remote URL: %w", err)
349		}
350	
351		checkpointURL, err := deriveCheckpointURLFromInfo(remoteInfo, config)
352		if err != nil {
353			return "", true, fmt.Errorf("could not derive checkpoint URL: %w", err)
354		}
355	
356		return checkpointURL, true, nil
