236	// GetLatestCheckpointIDFromHistory walks backwards from HEAD and returns
237	// the checkpoint ID from the first commit with an Entire-Checkpoint trailer.
238	// Returns an error if no checkpoint trailer is found in any commit.
239	func GetLatestCheckpointIDFromHistory(t *testing.T, repoDir string) (string, error) {
240		t.Helper()
241	
242		repo, err := git.PlainOpen(repoDir)
243		if err != nil {
244			t.Fatalf("failed to open git repo: %v", err)
245		}
246	
247		head, err := repo.Head()
248		if err != nil {
249			t.Fatalf("failed to get HEAD: %v", err)
250		}
251	
252		commitIter, err := repo.Log(&git.LogOptions{From: head.Hash()})
253		if err != nil {
254			t.Fatalf("failed to iterate commits: %v", err)
255		}
256	
257		var checkpointID string
258		//nolint:errcheck,gosec // ForEach callback returns error to stop iteration
259		commitIter.ForEach(func(c *object.Commit) error {
260			// Look for Entire-Checkpoint trailer
261			for line := range strings.SplitSeq(c.Message, "\n") {
262				line = strings.TrimSpace(line)
263				if value, found := strings.CutPrefix(line, "Entire-Checkpoint:"); found {
264					checkpointID = strings.TrimSpace(value)
265					return errors.New("stop iteration")
266				}
267			}
268			return nil
269		})
270	
271		if checkpointID == "" {
272			return "", errors.New("no commit with Entire-Checkpoint trailer found in history")
273		}
274	
275		return checkpointID, nil
276	}
