288	// GIT_CONFIG_GLOBAL/GIT_CONFIG_SYSTEM. We use an empty file instead of
289	// os.DevNull because git on Windows cannot open NUL as a config file.
290	var gitEmptyConfig string
291	var gitEmptyConfigOnce sync.Once
292	
293	func gitEmptyConfigPath() string {
294		gitEmptyConfigOnce.Do(func() {
295			f, err := os.CreateTemp("", "git-empty-config-*")
296			if err != nil {
297				panic("create empty git config: " + err.Error())
298			}
299			_ = f.Close()
300			gitEmptyConfig = f.Name()
301		})
302		return gitEmptyConfig
