305	// GitIsolatedEnv returns os.Environ() with git isolation variables set.
306	// This prevents user/system git config (global gitignore, aliases, etc.) from
307	// affecting test behavior. Use this for any exec.Command that runs git or the
308	// CLI binary in integration tests.
309	//
310	// See https://git-scm.com/docs/git#Documentation/git.txt-GITCONFIGGLOBAL
311	//
312	// Existing GIT_CONFIG_GLOBAL/GIT_CONFIG_SYSTEM entries are filtered out before
313	// appending overrides to ensure they take effect regardless of parent env.
314	func GitIsolatedEnv() []string {
315		env := os.Environ()
316		filtered := make([]string, 0, len(env)+2)
317		for _, e := range env {
318			if strings.HasPrefix(e, "GIT_CONFIG_GLOBAL=") || strings.HasPrefix(e, "GIT_CONFIG_SYSTEM=") {
319				continue
320			}
321			filtered = append(filtered, e)
322		}
323		return append(filtered,
324			"GIT_CONFIG_GLOBAL="+gitEmptyConfigPath(), // Isolate from user's global git config (e.g. global gitignore)
325			"GIT_CONFIG_SYSTEM="+gitEmptyConfigPath(), // Isolate from system git config
326		)
327	}
